export interface RawgGameLite {
  id: string
  name: string
  coverUrl: string
  rating: number // 百分制 0-100
  ratingCount: number
  releaseDate: string
  platforms: string[]
  genres: string[]
  tags: string[]
  description: string
  rawgUrl: string
  metacritic: number | null
  developer: string
  priceLabel: string
}

